.rd-section {
  font-family: 'Source Serif Pro', serif;
  color: var(--ink, #1a2b4a);
  background: var(--paper, #f8f9fa);
  padding: 2rem;
  line-height: 1.6;
}

.rd-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  max-width: 1200px;
  margin: 0 auto;
}

.rd-narrative h2 {
  font-size: 1.8rem;
  margin-bottom: 1.5rem;
  color: var(--ink, #1a2b4a);
}

.rd-narrative p {
  margin-bottom: 1rem;
  font-size: 1rem;
}

.formula-block {
  background: rgba(26, 43, 74, 0.05);
  padding: 1.5rem;
  border-left: 4px solid var(--accent, #007acc);
  margin: 1.5rem 0;
}

.math-display {
  font-family: 'Latin Modern Math', 'STIX Math', serif;
  font-size: 1.2rem;
  text-align: center;
  padding: 1rem 0;
  color: var(--ink, #1a2b4a);
}

.source-btn {
  background: transparent;
  border: 1px solid var(--muted, #6c757d);
  color: var(--muted, #6c757d);
  padding: 0.25rem 0.5rem;
  font-size: 0.8rem;
  margin-right: 0.5rem;
  cursor: pointer;
  transition: all 0.2s;
}

.source-btn:hover {
  border-color: var(--accent, #007acc);
  color: var(--accent, #007acc);
}

.rd-interactive {
  background: rgba(255, 255, 255, 0.8);
  backdrop-filter: blur(10px);
  padding: 2rem;
  border-radius: 8px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
}

.control-panel {
  margin-bottom: 2rem;
}

.control-panel label {
  display: block;
  margin-bottom: 0.5rem;
  font-weight: 600;
  color: var(--ink, #1a2b4a);
}

.control-panel input[type="range"] {
  width: 100%;
  margin-bottom: 0.5rem;
}

.value-display {
  text-align: right;
  font-family: monospace;
  color: var(--accent, #007acc);
  margin-bottom: 1rem;
}

.chart-container {
  position: relative;
  margin-bottom: 1.5rem;
}

#rd-canvas {
  width: 100%;
  height: auto;
  border: 1px solid var(--line, #dee2e6);
  background: white;
}

.chart-legend {
  display: flex;
  gap: 1rem;
  font-size: 0.8rem;
  margin-top: 0.5rem;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.color-box {
  width: 12px;
  height: 12px;
  border-radius: 2px;
}

.result-panel {
  background: rgba(26, 43, 74, 0.05);
  padding: 1rem;
  border-radius: 4px;
}

.result-panel h3 {
  margin-top: 0;
  font-size: 1.2rem;
  color: var(--ink, #1a2b4a);
}

.result-row {
  display: flex;
  justify-content: space-between;
  margin-bottom: 0.5rem;
  font-size: 0.9rem;
}

.result-value {
  font-weight: 600;
  color: var(--accent, #007acc);
}

.teaching-note {
  font-size: 0.8rem;
  color: var(--muted, #6c757d);
  font-style: italic;
  margin: 1rem 0;
}

#reset-btn {
  background: var(--accent, #007acc);
  color: white;
  border: none;
  padding: 0.5rem 1rem;
  border-radius: 4px;
  cursor: pointer;
  font-size: 0.9rem;
}

#reset-btn:hover {
  background: #005a99;
}

@media (max-width: 768px) {
  .rd-layout {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .rd-interactive {
    order: -1;
  }
}
