(function() {
  const canvas = document.getElementById('rd-canvas');
  const ctx = canvas.getContext('2d');
  const dSlider = document.getElementById('distortion-slider');
  const pSlider = document.getElementById('power-slider');
  const dValue = document.getElementById('d-value');
  const pValue = document.getElementById('p-value');
  const rateResult = document.getElementById('rate-result');
  const resetBtn = document.getElementById('reset-btn');

  let currentD = parseFloat(dSlider.value);
  let currentP = parseFloat(pSlider.value);

  function calculateRate(d, p) {
    if (d <= 0) return Infinity;
    if (d >= p) return 0;
    return 0.5 * Math.log2(p / d);
  }

  function drawChart() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const padding = 40;
    const chartWidth = canvas.width - 2 * padding;
    const chartHeight = canvas.height - 2 * padding;

    ctx.strokeStyle = '#dee2e6';
    ctx.lineWidth = 1;

    for (let i = 0; i <= 5; i++) {
      const x = padding + (i / 5) * chartWidth;
      const y = padding + (i / 5) * chartHeight;

      ctx.beginPath();
      ctx.moveTo(x, padding);
      ctx.lineTo(x, canvas.height - padding);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(canvas.width - padding, y);
      ctx.stroke();

      ctx.fillStyle = '#6c757d';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText((i / 5).toFixed(1), x, canvas.height - padding + 15);

      ctx.textAlign = 'right';
      ctx.fillText((3 - i * 0.6).toFixed(1), padding - 5, y + 3);
    }

    ctx.strokeStyle = '#1a2b4a';
    ctx.lineWidth = 2;
    ctx.beginPath();

    const maxRate = calculateRate(0.01, currentP);
    const points = [];

    for (let i = 0; i <= 100; i++) {
      const d = 0.01 + (i / 100) * (currentP - 0.01);
      const r = calculateRate(d, currentP);

      const x = padding + (d / currentP) * chartWidth;
      const y = canvas.height - padding - (r / (maxRate || 1)) * chartHeight;

      points.push({x, y, d, r});

      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    }
    ctx.stroke();

    const currentRate = calculateRate(currentD, currentP);
    const currentX = padding + (currentD / currentP) * chartWidth;
    const currentY = canvas.height - padding - (currentRate / (maxRate || 1)) * chartHeight;

    ctx.fillStyle = '#007acc';
    ctx.beginPath();
    ctx.arc(currentX, currentY, 6, 0, 2 * Math.PI);
    ctx.fill();

    ctx.strokeStyle = '#007acc';
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    ctx.moveTo(currentX, canvas.height - padding);
    ctx.lineTo(currentX, currentY);
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(padding, currentY);
    ctx.lineTo(currentX, currentY);
    ctx.stroke();
    ctx.setLineDash([]);

    ctx.fillStyle = '#1a2b4a';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('D (Distortion)', canvas.width / 2, canvas.height - 10);

    ctx.save();
    ctx.translate(15, canvas.height / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.fillText('R (Rate)', 0, 0);
    ctx.restore();
  }

  function updateResults() {
    const rate = calculateRate(currentD, currentP);

    dValue.textContent = currentD.toFixed(2);
    dValue.setAttribute('data-value', currentD.toFixed(2));
    pValue.textContent = currentP.toFixed(1);
    pValue.setAttribute('data-value', currentP.toFixed(1));

    if (rate === Infinity) {
      rateResult.textContent = '∞';
      rateResult.setAttribute('data-value', 'Infinity');
    } else {
      rateResult.textContent = rate.toFixed(2) + ' bits/sample';
      rateResult.setAttribute('data-value', rate.toFixed(2));
    }
  }

  function handleInput() {
    currentD = parseFloat(dSlider.value);
    currentP = parseFloat(pSlider.value);
    drawChart();
    updateResults();
  }

  dSlider.addEventListener('input', handleInput);
  pSlider.addEventListener('input', handleInput);

  resetBtn.addEventListener('click', function() {
    dSlider.value = 0.1;
    pSlider.value = 5.0;
    currentD = 0.1;
    currentP = 5.0;
    handleInput();
  });

  handleInput();
})();
